import {
    BrowserRouter as Router,
    Switch,
    Route
} from 'react-router-dom'


const App =()=>{

    return(
        <Router>
        <div className="container">
            <NavBar/>
            <switch>
                <Route path={"/"}>

                </Route>

            </switch>
        </div>
        </Router>


    )
}

ReactDOM.render(<App/>, document.getElementById('root'));
